CREATE TABLE whatsapp_templates (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, account_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, meta_id VARCHAR(64) NULL, name VARCHAR(512) NOT NULL, language VARCHAR(10) NOT NULL, category VARCHAR(20) NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'PENDING', body TEXT NOT NULL, footer VARCHAR(255) NULL, buttons JSON NOT NULL, variables JSON NOT NULL, purpose VARCHAR(20) NOT NULL DEFAULT 'custom', synced_at DATETIME(6) NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (id), UNIQUE KEY whatsapp_templates_name_uq (account_id,name(191),language), UNIQUE KEY whatsapp_templates_owner_uq (id,user_id), KEY whatsapp_templates_owner_idx (user_id,status), CONSTRAINT whatsapp_templates_purpose_ck CHECK (purpose IN ('custom','order_confirmation','greeting','external')), CONSTRAINT whatsapp_templates_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT whatsapp_templates_account_fk FOREIGN KEY (account_id,user_id) REFERENCES whatsapp_accounts(id,user_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci